  {s : (i : ι) → Set (α i)} {I : Set ι} (hI : I.Finite) (h : ∀ i ∈ I, s i ∈ f i) :
  I.pi s ∈ Filter.pi f

theorem Filter.Tendsto.pi_map_coprodᵢ.{u_1, u_2, u_3} {ι : Type u_1} {α : ι → Type u_2}
  {f : (i : ι) → Filter (α i)} {β : ι → Type u_3} {m : (i : ι) → α i → β i}
  {g : (i : ι) → Filter (β i)} (h : ∀ (i : ι), Filter.Tendsto (m i) (f i) (g i)) :
  Filter.Tendsto (fun k i => m i (k i)) (Filter.coprodᵢ f) (Filter.coprodᵢ g)

theorem Filter.Eventually.eval_pi.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {f : (i : ι) → Filter (α i)}
  {p : (i : ι) → α i → Prop} {i : ι} (hf : ∀ᶠ (x : α i) in f i, p i x) :
  ∀ᶠ (x : (i : ι) → α i) in Filter.pi f, p i (x i)

theorem Filter.pi_mem_pi_iff.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {f : (i : ι) → Filter (α i)}
  {s : (i : ι) → Set (α i)} [∀ (i : ι), (f i).NeBot] {I : Set ι} (hI : I.Finite) :
  I.pi s ∈ Filter.pi f ↔ ∀ i ∈ I, s i ∈ f i

theorem Filter.le_pi.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {f : (i : ι) → Filter (α i)}
  {g : Filter ((i : ι) → α i)} :
  g ≤ Filter.pi f ↔ ∀ (i : ι), Filter.Tendsto (Function.eval i) g (f i)

theorem Filter.mem_coprodᵢ_iff.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {f : (i : ι) → Filter (α i)}
  {s : Set ((i : ι) → α i)} :
  s ∈ Filter.coprodᵢ f ↔ ∀ (i : ι), ∃ t₁ ∈ f i, Function.eval i ⁻¹' t₁ ⊆ s

theorem Filter.pi_inf_principal_pi_eq_bot.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2}
  {f : (i : ι) → Filter (α i)} {s : (i : ι) → Set (α i)} [∀ (i : ι), (f i).NeBot] {I : Set ι} :
  Filter.pi f ⊓ Filter.principal (I.pi s) = ⊥ ↔ ∃ i ∈ I, f i ⊓ Filter.principal (s i) = ⊥

theorem Filter.pi_comap.{u_1, u_2, u_3} {ι : Type u_1} {α : ι → Type u_2} {β : ι → Type u_3}
  {f : (i : ι) → α i → β i} {l : (i : ι) → Filter (β i)} :
  (Filter.pi fun i => Filter.comap (f i) (l i)) = Filter.comap (Pi.map f) (Filter.pi l)

theorem Filter.tendsto_pi.{u_1, u_2, u_3} {ι : Type u_1} {α : ι → Type u_2} {f : (i : ι) → Filter (α i)}
  {β : Type u_3} {m : β → (i : ι) → α i} {l : Filter β} :
  Filter.Tendsto m l (Filter.pi f) ↔ ∀ (i : ι), Filter.Tendsto (fun x => m x i) l (f i)

theorem Filter.hasBasis_pi.{u_1, u_2, u_3} {ι : Type u_1} {α : ι → Type u_2} {f : (i : ι) → Filter (α i)}
  {ι' : ι → Type u_3} {s : (i : ι) → ι' i → Set (α i)} {p : (i : ι) → ι' i → Prop}
  (h : ∀ (i : ι), (f i).HasBasis (p i) (s i)) :
  (Filter.pi f).HasBasis (fun If => If.1.Finite ∧ ∀ i ∈ If.1, p i (If.2 i)) fun If =>
    If.1.pi fun i => s i (If.2 i)

theorem Filter.pi_inf_principal_univ_pi_eq_bot.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2}
  {f : (i : ι) → Filter (α i)} {s : (i : ι) → Set (α i)} :
  Filter.pi f ⊓ Filter.principal (Set.univ.pi s) = ⊥ ↔ ∃ i, f i ⊓ Filter.principal (s i) = ⊥

theorem Filter.HasBasis.pi_self.{u_1, u_3, u_4} {ι : Type u_1} {α : Type u_3} {κ : Type u_4} {f : Filter α}
  {p : κ → Prop} {s : κ → Set α} (h : f.HasBasis p s) :
  (Filter.pi fun x => f).HasBasis (fun Ik => Ik.1.Finite ∧ p Ik.2) fun Ik => Ik.1.pi fun x => s Ik.2

theorem Filter.hasBasis_pi_principal.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2}
  (s : (i : ι) → Set (α i)) :
  (Filter.pi fun i => Filter.principal (s i)).HasBasis Set.Finite fun x => x.pi s

theorem Filter.tendsto_piMap_pi.{u_1, u_2, u_3} {ι : Type u_1} {α : ι → Type u_2} {β : ι → Type u_3}
  {f : (i : ι) → α i → β i} {l : (i : ι) → Filter (α i)} {l' : (i : ι) → Filter (β i)}
  (h : ∀ (i : ι), Filter.Tendsto (f i) (l i) (l' i)) :
  Filter.Tendsto (Pi.map f) (Filter.pi l) (Filter.pi l')

theorem Filter.PiInfPrincipalPi.neBot.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2}
  {f : (i : ι) → Filter (α i)} {s : (i : ι) → Set (α i)}
  [h : ∀ (i : ι), (f i ⊓ Filter.principal (s i)).NeBot] {I : Set ι} :
  (Filter.pi f ⊓ Filter.principal (I.pi s)).NeBot

doc:
Given a collection of filters `l i : Filter (α i)` and sets `s i ∈ l i`,
if all but finitely many of `s i` are the whole space,
then their indexed product `Set.pi Set.univ s` belongs to the filter `Filter.pi l`.

